"""Validate an original reviewed Native roundabout source packet before launch."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from capture_roundabout import CAMERAS
from native_roundabout import load_case


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def load_reviewed(path, expected_case_id):
    review_path = Path(path).resolve()
    review = json.loads(review_path.read_text())
    if review.get("case_id") != expected_case_id or review.get("review_status") != "reviewed_original":
        raise ValueError("exact original roundabout source review required")
    refs = review.get("sources")
    if not isinstance(refs, dict) or set(refs) != {"opendrive", "construction_packet", "camera_placement"}:
        raise ValueError("original roundabout source inventory incomplete")
    sources = {}
    for name, ref in refs.items():
        source = Path(ref["path"])
        if not source.is_absolute():
            source = review_path.parent / source
        source = source.resolve()
        if not source.is_file() or _sha(source) != ref.get("sha256"):
            raise ValueError("review source changed before Native launch: " + name)
        sources[name] = source
    packet = load_case(sources["construction_packet"], refs["construction_packet"]["sha256"],
                       expected_case_id)
    if _sha(sources["opendrive"]) != packet["map_sha256"]:
        raise ValueError("reviewed original OpenDRIVE does not match map packet")
    placement = json.loads(sources["camera_placement"].read_text())
    if set(placement.get("cameras", {})) != set(CAMERAS):
        raise ValueError("four original camera placements required")
    for name in CAMERAS:
        row = placement["cameras"][name]
        for key in ("location_xyz_m", "pitch_yaw_roll_deg"):
            values = row.get(key)
            if not isinstance(values, list) or len(values) != 3 or not all(
                    type(value) in (int, float) for value in values):
                raise ValueError("original camera pose missing: " + name)
    return {"review_sha256": _sha(review_path), "sources": sources,
            "packet": packet, "placement": placement}

"""Lazy source-bound construction and timed roundabout entry controls.

Release ticks are engineering requests. The original capture must later prove
the actual gap, yielding, lane use, and physical completion.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from roundabout_measurements import ASSIGNMENT_ID, SUFFIXES, validate_map


def _route(points, name):
    if not isinstance(points, list) or len(points) < 3:
        raise ValueError(f"{name} source route too short")
    for index, point in enumerate(points):
        if not all(isinstance(point.get(key), (int, float)) and math.isfinite(point[key])
                   for key in ("x", "y", "speed_mps")):
            raise ValueError(f"{name} route sample invalid")
        if not 0 < point["speed_mps"] <= 20 or not point.get("lane_id"):
            raise ValueError(f"{name} route speed/lane missing")
        if index:
            previous = points[index-1]
            step = math.hypot(point["x"]-previous["x"], point["y"]-previous["y"])
            if not .15 <= step <= 8:
                raise ValueError(f"{name} route samples disconnected")
    return points


def load_case(path: str | Path, expected_sha256: str, case_id: str) -> dict:
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("original construction source hash mismatch")
    packet = json.loads(raw)
    if case_id not in {ASSIGNMENT_ID + "__" + name for name in SUFFIXES} or packet.get("case_id") != case_id:
        raise ValueError("exact roundabout case mismatch")
    validate_map(packet)
    if not packet.get("map_name") or not packet.get("route_source_sha256"):
        raise ValueError("live map and route source missing")
    ego = _route(packet.get("ego_route"), "ego")
    other = _route(packet.get("opponent_points"), "opponent")
    if ego[0]["lane_id"] != packet["ego_entry_lane"]["lane_id"] or ego[-1]["lane_id"] != packet["ego_entry_lane"]["connected_circulating_lane_id"]:
        raise ValueError("ego route lane connection mismatch")
    if any(p["lane_id"] != packet["opponent_route"]["circulating_lane_id"] for p in other):
        raise ValueError("opponent route circulating lane mismatch")
    if not all(packet.get(key, "").startswith("vehicle.") for key in ("ego_blueprint", "opponent_blueprint")):
        raise ValueError("two source-selected vehicle blueprints required")
    if not all(isinstance(packet.get(key), int) and 0 <= packet[key] < 900
               for key in ("ego_release_tick", "opponent_release_tick")):
        raise ValueError("source-selected release ticks required")
    if not packet.get("ego_spawn") or not packet.get("opponent_spawn"):
        raise ValueError("source-selected spawn transforms required")
    return packet


def spawn(world, packet, transform_factory):
    """Spawn two distinct actors after the reviewed map and route are loaded."""
    if world.get_map().name != packet["map_name"]:
        raise ValueError("wrong live roundabout map")
    library = world.get_blueprint_library()
    ego = world.try_spawn_actor(library.find(packet["ego_blueprint"]),
                                transform_factory(packet["ego_spawn"]))
    if ego is None:
        raise RuntimeError("ego spawn failed")
    try:
        other = world.try_spawn_actor(library.find(packet["opponent_blueprint"]),
                                      transform_factory(packet["opponent_spawn"]))
        if other is None or other.id == ego.id:
            raise RuntimeError("distinct opponent spawn failed")
        return ego, other
    except Exception:
        ego.destroy()
        raise


class TimedRoute:
    """Follow original route samples after a configured release tick."""
    def __init__(self, points, release_tick, control_factory, *, throttle=0.35):
        self.points = _route(points, "vehicle")
        if not isinstance(release_tick, int) or not 0 <= release_tick < 900:
            raise ValueError("invalid release tick")
        self.release_tick = release_tick
        self.factory = control_factory
        if type(throttle) not in (int, float) or not 0 < throttle <= .5:
            raise ValueError("bounded engineering throttle required")
        self.throttle = float(throttle)
        self.index = 1

    def __call__(self, actor, tick):
        if not isinstance(tick, int) or tick < 0:
            raise ValueError("invalid Native tick")
        if tick < self.release_tick or self.index == len(self.points):
            actor.apply_control(self.factory(throttle=0.0, steer=0.0, brake=1.0))
            return
        pose = actor.get_transform()
        x, y = float(pose.location.x), float(pose.location.y)
        yaw = math.radians(float(pose.rotation.yaw))
        if not all(math.isfinite(v) for v in (x, y, yaw)):
            raise ValueError("nonfinite original vehicle pose")
        target = self.points[self.index]
        distance = math.hypot(target["x"]-x, target["y"]-y)
        if distance < .8:
            self.index += 1
            if self.index == len(self.points):
                actor.apply_control(self.factory(throttle=0.0, steer=0.0, brake=1.0))
                return
            target = self.points[self.index]
            distance = math.hypot(target["x"]-x, target["y"]-y)
        previous = self.points[self.index-1]
        dx, dy = target["x"]-previous["x"], target["y"]-previous["y"]
        cross_track = abs((x-previous["x"])*dy-(y-previous["y"])*dx)/math.hypot(dx,dy)
        if cross_track > 4:
            raise ValueError("original route tracking lost")
        heading = math.atan2(target["y"]-y, target["x"]-x)
        error = (heading-yaw+math.pi)%(2*math.pi)-math.pi
        steer = max(-1.0,min(1.0,math.atan(2.7*2*math.sin(error)/max(distance,.8))/.65))
        actor.apply_control(self.factory(throttle=self.throttle, steer=steer, brake=0.0))

"""Lazy CARLA frame and vehicle body bridges for original roundabout capture."""

from __future__ import annotations

from collections import deque
from io import BytesIO
from threading import Condition
from time import monotonic

from PIL import Image

from capture_roundabout import CAMERAS, CAMERA_DIMENSIONS


class CameraFrames:
    """Join four CARLA BGRA callbacks to the frame returned by world.tick()."""

    def __init__(self, dimensions=None, *, max_pending=4, frame_timeout_s=10):
        self.dimensions = dict(dimensions or CAMERA_DIMENSIONS)
        if set(self.dimensions) != set(CAMERAS):
            raise ValueError("four named camera dimensions required")
        if not isinstance(max_pending, int) or max_pending < 1:
            raise ValueError("positive camera buffer bound required")
        if not isinstance(frame_timeout_s, (int, float)) or frame_timeout_s <= 0:
            raise ValueError("positive camera frame timeout required")
        self.max_pending = max_pending
        self.frame_timeout_s = float(frame_timeout_s)
        self.condition = Condition()
        self.errors = {name: None for name in CAMERAS}
        self.pending = {name: {} for name in CAMERAS}
        self.order = {name: deque() for name in CAMERAS}

    def callback(self, name):
        if name not in self.pending:
            raise ValueError("unknown camera name")

        def receive(image):
            try:
                frame = int(image.frame)
                width, height = self.dimensions[name]
                if (image.width, image.height) != (width, height):
                    raise ValueError("original camera dimensions mismatch")
                raw = bytes(image.raw_data)
                if len(raw) != width * height * 4:
                    raise ValueError("original BGRA byte count mismatch")
                decoded = Image.frombytes("RGBA", (width, height), raw, "raw", "BGRA").convert("RGB")
                stream = BytesIO()
                decoded.save(stream, format="PNG")
                with self.condition:
                    if frame in self.pending[name]:
                        raise ValueError("duplicate original camera frame")
                    self.pending[name][frame] = stream.getvalue()
                    self.order[name].append(frame)
                    if len(self.order[name]) > self.max_pending:
                        old = self.order[name].popleft()
                        del self.pending[name][old]
                    self.condition.notify_all()
            except BaseException as error:
                with self.condition:
                    self.errors[name] = error
                    self.condition.notify_all()

        return receive

    def reader(self, name):
        if name not in self.pending:
            raise ValueError("unknown camera name")

        def read(frame):
            deadline = monotonic() + self.frame_timeout_s
            with self.condition:
                while frame not in self.pending[name]:
                    if self.errors[name] is not None:
                        raise ValueError("original camera callback failed") from self.errors[name]
                    remaining = deadline - monotonic()
                    if remaining <= 0:
                        raise ValueError("original camera frame unavailable")
                    self.condition.wait(remaining)
                self.order[name].remove(frame)
                return {"frame": frame, "png_bytes": self.pending[name].pop(frame)}

        return read

    def readers(self):
        return {name: self.reader(name) for name in CAMERAS}


def body_vertices(actor):
    """Read eight current world-space CARLA bounding-box vertices."""
    points = actor.bounding_box.get_world_vertices(actor.get_transform())
    return [[float(point.x), float(point.y), float(point.z)] for point in points]

"""Saved Native geometry and motion audit for LVMC 11.43.010(B).

The outputs are physical observations. No distance or time in this module is a
legal definition of a traffic gap or a right-of-way judgment.
"""

import argparse
import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT_ID = "testing__C130864__LVMC-11-43-010-B__motor_vehicle_driver"
SUFFIXES = ("connected_wait", "connected_enter", "adjacent_wait", "adjacent_enter",
            "connected_gap_wait", "connected_gap_enter")


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _point(p):
    if not isinstance(p, list) or len(p) != 2 or any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in p):
        raise ValueError("finite two-dimensional point required")
    return p


def _polygon(p):
    if not isinstance(p, list) or len(p) < 3:
        raise ValueError("source-backed polygon required")
    return [_point(v) for v in p]


def _inside(point, polygon):
    x, y = point
    result = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > y) != (b[1] > y):
            x_at_y = (b[0] - a[0]) * (y - a[1]) / (b[1] - a[1]) + a[0]
            if x < x_at_y:
                result = not result
    return result


def validate_map(packet):
    if packet.get("layout") != "multilane_roundabout" or not packet.get("map_sha256") or len(packet["map_sha256"]) != 64:
        raise ValueError("source-hashed multilane roundabout map required")
    if not packet.get("jurisdiction_source") or not packet.get("roundabout_geometry_source"):
        raise ValueError("jurisdiction and original roundabout geometry sources required")
    ring = _polygon(packet.get("circulating_surface_polygon"))
    conflict = _polygon(packet.get("entry_conflict_polygon"))
    lanes = packet.get("circulating_lanes")
    if not isinstance(lanes, list) or len(lanes) < 2 or len({lane.get("lane_id") for lane in lanes}) != len(lanes):
        raise ValueError("two distinct circulating lanes required")
    entry = packet.get("ego_entry_lane")
    if not isinstance(entry, dict) or not entry.get("lane_id") or not entry.get("connected_circulating_lane_id"):
        raise ValueError("ego entry and connected circulating lane required")
    if entry["connected_circulating_lane_id"] not in {lane["lane_id"] for lane in lanes}:
        raise ValueError("ego entry lane is not connected to an inventoried circulating lane")
    other = packet.get("opponent_route")
    if not isinstance(other, dict) or other.get("circulating_lane_id") not in {lane["lane_id"] for lane in lanes}:
        raise ValueError("opponent actual circulating lane and route required")
    if not other.get("route_source") or not other.get("potential_conflict_source"):
        raise ValueError("opponent route/conflict source required")
    if not _inside(_point(other.get("initial_position")), ring):
        raise ValueError("opponent must start inside roundabout")
    line = packet.get("entry_line")
    if not isinstance(line, list) or len(line) != 2 or _point(line[0]) == _point(line[1]):
        raise ValueError("physical entry line required")
    return ring, conflict


def _body(vertices):
    if not isinstance(vertices, list) or len(vertices) != 8:
        raise ValueError("eight original world-space body vertices required")
    result = []
    for vertex in vertices:
        if not isinstance(vertex, list) or len(vertex) != 3 or any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in vertex):
            raise ValueError("finite three-dimensional body vertex required")
        result.append(vertex[:2])
    return result


def _minimum_distance(a, b):
    return min(math.dist(x, y) for x in a for y in b)


def measure(*, case_id, map_path, trace_path, receipt_path,
            allow_diagnostic=False):
    if case_id not in {ASSIGNMENT_ID + "__" + suffix for suffix in SUFFIXES}:
        raise ValueError("unknown exact case ID")
    receipt = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
    if (receipt.get("assignment_id"), receipt.get("case_id")) != (ASSIGNMENT_ID, case_id):
        raise ValueError("source receipt identity mismatch")
    if receipt.get("diagnostic_fixture") and not allow_diagnostic:
        raise ValueError("diagnostic fixture is not delivery evidence")
    if _sha(map_path) != receipt.get("map_sha256") or _sha(trace_path) != receipt.get("trace_sha256"):
        raise ValueError("original source bytes changed")
    packet = json.loads(Path(map_path).read_text(encoding="utf-8"))
    ring, conflict = validate_map(packet)
    if packet.get("case_id") != case_id:
        raise ValueError("original map case mismatch")
    rows = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(rows) < 2 or len(rows) != receipt.get("frame_count") or receipt.get("fps") != 20:
        raise ValueError("original 20 Hz frame count mismatch")
    observations = []
    previous = None
    for row in rows:
        frame, time_s = row.get("frame"), row.get("time_s")
        if not isinstance(frame, int) or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
            raise ValueError("original frame/time missing")
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > .002):
            raise ValueError("original frame order or 20 Hz cadence mismatch")
        previous = frame, time_s
        ego, opponent = _body(row.get("ego_vertices")), _body(row.get("opponent_vertices"))
        ego_in_ring = any(_inside(p, ring) for p in ego)
        opponent_in_ring = any(_inside(p, ring) for p in opponent)
        ego_in_conflict = any(_inside(p, conflict) for p in ego)
        opponent_in_conflict = any(_inside(p, conflict) for p in opponent)
        for key in ("ego_speed_mps", "opponent_speed_mps"):
            if not isinstance(row.get(key), (int, float)) or not math.isfinite(row[key]) or row[key] < 0:
                raise ValueError("original vehicle speed missing")
        observations.append({"frame": frame, "time_s": time_s,
                             "ego_in_ring": ego_in_ring, "opponent_in_ring": opponent_in_ring,
                             "ego_in_conflict": ego_in_conflict, "opponent_in_conflict": opponent_in_conflict,
                             "body_vertex_separation_m": _minimum_distance(ego, opponent),
                             "ego_speed_mps": row["ego_speed_mps"],
                             "opponent_speed_mps": row["opponent_speed_mps"]})
    first_entry = next((r for previous_row, r in zip(observations, observations[1:])
                        if not previous_row["ego_in_ring"] and r["ego_in_ring"]), None)
    before_entry = [r for r in observations if first_entry is None or r["frame"] < first_entry["frame"]]
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "source_bindings": {"map_packet_sha256": _sha(map_path),
                                "original_trace_sha256": _sha(trace_path),
                                "receipt_sha256": _sha(receipt_path),
                                "native_map_sha256": packet["map_sha256"]},
            "ego_entry_lane_id": packet["ego_entry_lane"]["lane_id"],
            "connected_circulating_lane_id": packet["ego_entry_lane"]["connected_circulating_lane_id"],
            "opponent_circulating_lane_id": packet["opponent_route"]["circulating_lane_id"],
            "first_observed_ego_entry_frame": first_entry["frame"] if first_entry else None,
            "opponent_in_ring_at_ego_entry": first_entry["opponent_in_ring"] if first_entry else None,
            "opponent_in_conflict_at_ego_entry": first_entry["opponent_in_conflict"] if first_entry else None,
            "ego_stopped_before_entry_frames": [r["frame"] for r in before_entry if r["ego_speed_mps"] <= .1],
            "body_separation_at_entry_m": first_entry["body_vertex_separation_m"] if first_entry else None,
            "minimum_sampled_body_separation_m": min(r["body_vertex_separation_m"] for r in observations),
            "observations": observations, "legal_gap_judgment": "unresolved",
            "physical_acceptance": "unverified",
            "diagnostic_fixture": bool(receipt.get("diagnostic_fixture"))}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--case", required=True)
    parser.add_argument("--map", required=True)
    parser.add_argument("--trace", required=True)
    parser.add_argument("--receipt", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    result = measure(case_id=args.case, map_path=args.map, trace_path=args.trace, receipt_path=args.receipt)
    Path(args.output).write_text(json.dumps(result, sort_keys=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
